from wd_common import *
i=3
Z=lambda q,a:[('z',q),('b',a)]
def nut(): return '<ellipse rx="24" ry="20" fill="#8a5a2a"/><circle cx="-7" cy="-8" r="3" fill="#3a1a0a"/><circle cx="7" cy="-8" r="3" fill="#3a1a0a"/><circle cy="0" r="3" fill="#3a1a0a"/>'
def half(): return '<path d="M-24 0 a24 20 0 0 0 48 0z" fill="#8a5a2a"/><ellipse rx="22" ry="5" fill="#f4f1ea"/>'
def kalasha(): return '<path d="M-24 0 q-10 -24 6 -36 h36 q16 12 6 36z" fill="#c9a227"/>'+''.join(f'<path d="M0 -36 q{a} -16 {a*1.6} -10" stroke="#2f8a3a" stroke-width="6" fill="none"/>' for a in (-16,-8,8,16))+g(0,-44,.7,nut())
def palm(): return '<path d="M0 0 q-6 -60 4 -120" stroke="#8a6a3a" stroke-width="8" fill="none"/>'+''.join(f'<path d="M4 -120 q{a} -10 {a*2} 14" stroke="#2f8a3a" stroke-width="5" fill="none"/>' for a in (-30,-15,15,30))+g(4,-112,.4,nut())
def stone(): return '<rect x="-30" y="-14" width="60" height="14" fill="#8a8a7a"/>'
fw=foreword(i,['At the start of a new house, a new car, a new shop or a temple festival, someone lifts a coconut and smashes it on a stone. At the shrine the priest breaks it neatly in two, offers the white flesh and sweet water, and hands one half back. The coconut is the most common fruit in Hindu worship, and in the south almost no rite happens without it.',
 'This part explains the coconut’s names, why it stands for the self, the three eyes, its place on the kalaśa, the breaking, how it is offered and returned, its use at beginnings, weddings and Gaṇeśa’s shrine, and the teachers’ readings.',
 'Previous: '+L('/why-do-we/prasada/','prasāda')+'. Next: '+L('/why-do-we/bell/','the bell')+'. Gaṇeśa and beginnings: '+L('/ganesha/','Gaṇeśa')+'.'],Z('Why a coconut and not an apple?','Grow up near the coast and you will see why. And the coconut has a shell to break.'))
gl=glance([('Names','Nārikela; śrīphala, “fruit of Śrī”'),('Tree','Kalpavṛkṣa, the wish-fulfilling tree'),('Eyes','Three, read as Śiva’s three eyes'),('Kalaśa','Crowns the sacred pot with mango leaves'),('Breaking','On a stone, or split in two by hand'),('Inside','White flesh and sweet water: offered to the god'),('Returned','One half given back as prasāda'),('Beginnings','House, vehicle, shop, journey, festival'),('Gaṇeśa','Smashed before him as the remover of obstacles'),('Meaning','Breaking the ego to reach the sweet within')],
 S('A coconut, a kalaśa crowned with one, and halves offered before a deity',g(110,200,2,nut())+g(280,215,1.6,kalasha())+g(440,215,1.3,god('#e0a800'))+g(440,215,1,'<ellipse rx="40" ry="8" fill="#2f8a3a"/>'+g(-14,-6,.7,half())+g(14,-6,.7,half())),'#fff3cf',215),Z('Is it always broken?','On the kalaśa it stays whole. At the shrine and at beginnings, it is broken.'),'The fruit <b>that stands for us</b>.')
names=reading('names','THE NAMES','Śrīphala and the kalpavṛkṣa',S('A coconut palm on the coast with fruit',g(160,220,1.6,palm())+g(380,220,1.4,palm())+'<path d="M0 220 h560" stroke="#4aa3df" stroke-width="12"/>','#d8e8f0',230),
 ['<b>Nārikela.</b> The Sanskrit name; Kannaḍa tengu, Tamiḻ tēṅkāy.','<b>Śrīphala.</b> “Fruit of Śrī”: Lakṣmī’s fruit, auspicious and prosperous.','<b>Kalpavṛkṣa.</b> The coconut palm is often called the kalpavṛkṣa, the wish-fulfilling tree, because every part of it is useful: food, drink, oil, fibre, leaves, wood. (Popular name.)','<b>A legend.</b> A folk legend says the sage Viśvāmitra created the coconut tree while making a new heaven for King Triśaṅku. (Folk legend.)','<b>Coast.</b> In coastal Karnataka, Kerala and Tamil Nadu the coconut is part of daily life and every rite.'],Z('A tree that grants wishes?','It gives food, water, oil, rope and a roof. That is wish enough.'),'Every part <b>is useful</b>.')
self_=reading('self','THE COCONUT AS THE SELF','Shell, fibre, flesh, water',S('A coconut cut open showing husk, shell, white flesh and water, labelled',g(280,170,3,'<circle r="32" fill="#c9a66a"/><circle r="24" fill="#5a3a1a"/><circle r="20" fill="#f4f1ea"/><circle r="15" fill="#bfe3ff"/>')+T(120,60,'husk',11)+T(120,90,'shell',11)+T(450,70,'flesh',11)+T(450,110,'water',11),'#fff3cf',230),
 ['<b>Layers.</b> Rough husk, hard shell, white flesh, clear water: teachers compare them to the layers of a person. (Interpretation.)','<b>Husk and shell.</b> Desire and ego, hard to break. (Interpretation.)','<b>White flesh.</b> The pure mind within. (Interpretation.)','<b>Sweet water.</b> The inner self, clean and untouched. (Interpretation.)','<b>So.</b> Breaking the coconut before God is offering oneself, cracking the ego to reach what is sweet inside.'],Z('Do I have to believe all that to break one?','No. But it makes the crack mean more.'),'Break the shell, <b>find the sweet</b>.')
eyes=reading('eyes','THREE EYES','The face of Śiva',S('A coconut with three eyes like a face; Śiva’s three-eyed face beside it',g(170,170,3,nut())+g(400,200,1.6,god('#7a9aaa'))+'<ellipse cx="400" cy="110" rx="3" ry="6" fill="#d02a2a"/>','#e3eaf3',215),
 ['<b>Three eyes.</b> The coconut has three “eyes”, the pores at one end.','<b>Śiva.</b> They are often likened to Śiva’s three eyes: the coconut is the face of the three-eyed god. (Interpretation.)','<b>Breaking point.</b> The ridge line near the eyes is where a skilled hand splits it in two.','<b>Water.</b> One eye is soft enough to pierce, to drink the water.','<b>A face.</b> In folk practice the coconut stands in for a head, which is why it is offered as the self. (Common explanation.)'],Z('It does look like a face.','That is why it was chosen, many say.'),'A face <b>with three eyes</b>.')
kal=reading('kalasha','ON THE KALAŚA','Crowning the sacred pot',S('A kalaśa with mango leaves and a coconut wrapped in cloth, before a lamp',g(280,215,2.6,kalasha())+g(130,215,1.2,lamp())+g(430,215,1.2,lamp()),'#fff3cf',230),
 ['<b>Pūrṇakumbha.</b> A pot of water, mango leaves around its mouth and a coconut on top: the <b>pūrṇakumbha</b>, the full pot, sign of abundance.','<b>The god invited.</b> In many pūjās the deity is invoked into the kalaśa.','<b>Varamahālakṣmī.</b> The coconut is dressed as the Goddess’s face, as at '+L('/festivals/varamahalakshmi/','Varamahālakṣmī')+'.','<b>Welcome.</b> Guests of honour are received with the pūrṇakumbha.','<b>Not broken.</b> The kalaśa coconut is kept whole; later it may be cooked as prasāda.'],Z('Why mango leaves?','Auspicious, green, always available. The coconut sits on them like a crown.'),'The full pot, <b>crowned</b>.')
brk=reading('breaking','THE BREAKING','A clean split or a great smash',S('A priest splitting a coconut neatly; a man smashing one on a stone',g(160,215,1.3,person('#f4f1ea'))+g(200,150,1,half())+g(240,150,1,half())+g(400,215,1.4,person('#1d4f8a'))+g(400,215,1,stone())+''.join(f'<path d="M400 200 l{dx} {dy}" stroke="#f4f1ea" stroke-width="3"/>' for dx,dy in [(-30,-20),(30,-20),(-20,-30),(20,-30)]),'#fff3cf',215),
 ['<b>At the shrine.</b> The priest strikes it on its ridge so it splits into two neat halves; the water is caught or offered.','<b>Smashing.</b> At beginnings and before Gaṇeśa, devotees smash the coconut on a stone so it shatters.','<b>One stroke.</b> A clean break in one blow is thought auspicious. (Popular belief.)','<b>A bad nut?</b> If the inside is spoiled, many simply offer another; some read it as a sign, others say it means nothing. (Beliefs differ.)','<b>The pieces.</b> Pieces are shared as prasāda.'],Z('Does a spoiled coconut mean bad luck?','Some grandmothers say so. Most priests say: get another coconut.'),'Split <b>or smash</b>.')
offr=reading('offering','OFFERED AND RETURNED','Half for the god, half for you',S('Two coconut halves on a plate before a deity; one handed back',g(220,215,1.4,god('#e0a800'))+g(220,200,1,'<ellipse rx="40" ry="8" fill="#c9a227"/>'+g(-14,-6,.7,half())+g(14,-6,.7,half()))+g(420,215,1.4,person('#c0392b'))+g(420,160,.7,half()),'#fff3cf',215),
 ['<b>Archana.</b> At the temple, the devotee gives a coconut with flowers and fruit; the priest breaks it and offers it.','<b>One half back.</b> Usually one half (or both) returns to the devotee as prasāda.','<b>The water.</b> Coconut water is also used to bathe the deity in abhiṣeka.','<b>At home.</b> Families offer a coconut at festivals and use it in the naivedya.','<b>Cooking.</b> The returned coconut is cooked into sweets or chutney: prasāda for the family.'],Z('Why give it back?','You gave yourself; the god gives you back, blessed.'),'Given, <b>and given back</b>.')
begin=cards('beginnings','AT BEGINNINGS','House, car, shop, festival',fig_row('A house, a car, a shop and a temple flag, each with a coconut',[(ainmane(80) if False else '<rect x="-30" y="-30" width="60" height="30" fill="#e9d6c0"/><path d="M-36 -30 l36 -22 l36 22z" fill="#7a3b1f"/>',1),('<rect x="-34" y="-20" width="68" height="18" rx="6" fill="#3a6aa0"/><circle cx="-20" r="6" fill="#222"/><circle cx="20" r="6" fill="#222"/>',1),('<rect x="-30" y="-36" width="60" height="36" fill="#f4f1ea"/><rect x="-30" y="-44" width="60" height="10" fill="#c0392b"/>',1),(flagpole(),.5),(nut(),1)],['house','vehicle','shop','festival','coconut'],gy=150),
 [('🏠','New house','Gṛhapraveśa: a coconut broken at the threshold.'),('🚗','New vehicle','Coconut smashed before the wheels; lemons too, in many places.'),('🏪','New venture','Shops, offices and projects begin with a coconut.'),('🛕','Festivals','Temple festivals and chariot processions begin with coconuts smashed.'),('✈️','Journeys','Some break one before a long journey.'),('🎬','Even films','The first shot of a film begins with a coconut, in the south.')],None,'Nothing new <b>without a coconut</b>.',intro='The coconut asks Gaṇeśa to clear the way at any beginning.')
gan=reading('ganesha','BEFORE GAṆEŚA','Smashing for the remover of obstacles',S('Devotees smashing coconuts on a stone before a Gaṇeśa shrine',g(400,215,1.6,ganesha('#e08a2a')) if False else g(400,215,1.4,god('#e08a2a'))+g(200,215,1.6,person('#1d4f8a'))+g(260,215,1,stone())+''.join(g(220+k*30,200,.4,half()) for k in range(3)),'#fff3cf',215),
 ['<b>The custom.</b> At many Gaṇeśa shrines, especially in the south, devotees smash coconuts on a stone before the god.','<b>Obstacles.</b> Gaṇeśa removes obstacles; the shattered shell is read as obstacles broken. (Interpretation.)','<b>Vows.</b> People vow a number of coconuts for a wish fulfilled.','<b>Children.</b> Children scramble for the pieces as prasāda.','<b>See.</b> '+L('/ganesha/','Gaṇeśa')+' and his temples.'],Z('Why not just offer it whole?','Because the noise is the prayer. Crack: obstacle gone.'),'Crack, <b>obstacle gone</b>.')
wed=reading('weddings','GIVING A COCONUT','Respect, weddings and honour',S('A coconut with betel leaves and areca on a plate given to an elder',g(280,200,1.6,'<ellipse rx="40" ry="10" fill="#c9a227"/>'+g(0,-10,.8,nut())+'<ellipse cx="-26" cy="-6" rx="10" ry="6" fill="#2f8a3a"/><ellipse cx="26" cy="-6" rx="10" ry="6" fill="#2f8a3a"/>')+g(150,215,1.3,person('#c0392b'))+g(420,215,1.3,person('#f4f1ea')),'#fff3cf',215),
 ['<b>Tāmbūla.</b> In Karnataka, a coconut with betel leaves and areca nut is given to guests, elders and women at functions as a mark of respect.','<b>Weddings.</b> Coconuts are exchanged between families and used throughout the rites.','<b>Invitations.</b> A coconut may go with a wedding invitation to close family.','<b>Honour.</b> Teachers and priests are given coconuts as dakṣiṇā.','<b>Women’s gatherings.</b> Haḷadi-kuṅkuma often ends with a coconut and blouse piece.'],Z('A coconut as a present?','In Karnataka, the most respectful one. Ask any aunt.'),'Respect <b>you can hold</b>.')
endp=end(i,['<b>Names.</b> Nārikela, śrīphala; the kalpavṛkṣa tree.','<b>Symbol.</b> Shell, flesh and water as the layers of the self; three eyes as Śiva.','<b>Kalaśa.</b> Crowns the full pot, kept whole.','<b>Breaking.</b> Split at the shrine, smashed at beginnings and before Gaṇeśa.','<b>Returned.</b> Half comes back as prasāda; given as tāmbūla to honour.'],'Part 5 is the bell.','Break the shell, find the sweet')
src=sources([('Practice:','Common Hindu temple and household practice in Karnataka and south India (archana, pūrṇakumbha, gṛhapraveśa, tāmbūla); Wikipedia, “Coconut” (cultural uses, kalpavṛkṣa) and “Purna kalasha”; the site’s Gaṇeśa and Varamahālakṣmī articles.')],'the Viśvāmitra legend is folk tradition; readings of the layers and three eyes are interpretations; omens from spoiled coconuts are popular beliefs that differ.','No verse text is reproduced in this part.')
finish(i,'PART 4 OF 10 · ŚRĪPHALA · KALAŚA · BREAKING',covart('A coconut, a kalaśa and two halves offered before a deity',g(90,180,1.6,nut())+g(220,190,1.3,kalasha())+g(350,190,1,god('#e0a800'))+g(350,190,.8,'<ellipse rx="40" ry="8" fill="#2f8a3a"/>'+g(-14,-6,.7,half())+g(14,-6,.7,half()))),'Break the shell, find the sweet',
 'Why we break a <b>coconut</b>: śrīphala and the kalpavṛkṣa, shell and sweet water as the self, the three eyes, the <b>kalaśa</b>, the breaking, offering and return, beginnings and Gaṇeśa.',
 'Why do we break a coconut? Explained and illustrated: śrīphala, kalpavṛkṣa, the coconut as the self, three eyes, pūrṇakumbha, splitting and smashing, offering and prasāda, beginnings, Gaṇeśa and tāmbūla.',
 [fw,gl,names,self_,eyes,kal,brk,offr,begin,gan,wed,endp,src])
